//! The executable that OPENS the IDE (the Makepad shell).
//!
//! `ide_app::app_main()` is generated by `app_main!(IdeApp)`
//! (`makepad-platform-1.0.0/src/app_main.rs:19-22`); this file is its only
//! caller. Run it with:
//!
//! ```text
//! cargo run -p crawrad-ide
//! ```

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
#![forbid(unsafe_code)]

pub mod support;
pub mod view_models;

pub mod lines_editor {
    pub use crawrad_designer::lines_editor_model as model;
    pub use model::*;
}

pub mod action_list {
    pub use crawrad_actions::action_list as model;
    pub use model::*;
}

pub mod image_list_editor {
    pub use crawrad_designer::image_list_model as model;
    pub use model::*;
}

pub mod options {
    pub use crawrad_project::options as model;
    pub use model::*;
}

pub mod items_editor {
    pub use crawrad_actions::items_editor as model;
    pub use model::*;
}

#[path = "ide_app.rs"]
pub mod ide_app;

#[cfg(test)]
#[path = "test/crash_hook/test.rs"]
mod crash_hook_test;

fn main() {
    // A packaged build (tools/bundle) reads its fonts from `resources/` beside the exe.
    if option_env!("MAKEPAD_PACKAGE_DIR").is_some()
        && let Some(dir) = std::env::current_exe()
            .ok()
            .and_then(|e| e.parent().map(Into::into))
    {
        let _ = std::env::set_current_dir::<std::path::PathBuf>(dir);
    }
    std::panic::set_hook(Box::new(|info| {
        let backtrace = std::backtrace::Backtrace::force_capture();
        let details = format!("Backtrace:\n{backtrace}");
        // The box only in release: in debug the console is there, and a modal
        // box on every panic would get in the way.
        let _ = crawrad_os::crash_report::report(
            &info.to_string(),
            &details,
            crawrad_project::workspace::config_folder(),
            !cfg!(debug_assertions),
        );
    }));
    crawrad_splash::open(makepad_widgets::makepad_platform::shader_progress::progress);
    // Preloads the component catalog and builtin registry at IDE startup to eliminate any latency
    let _ = crawrad_project::installed::ide_catalog();
    let reg = crawrad_registry::Registry::builtin();
    let _ = crate::ide_app::palette::rows(&reg, crawrad_runtime_makepad::ALVO, "", false);
    ide_app::app_main();
}
